minimal-plugin.code:
window.CardSpoke.Plugin.register('my-plugin', {
  manifest: {
    name: 'My Plugin',
    version: '1.0.0',
    author: 'Your Name',
    description: 'Plugin description',
    layer: 'feature',
    permissions: []
  },
  setup: async function(ctx) {
    ctx.logger.info('Plugin enabled');
  },
  teardown: async function(ctx) {
    ctx.logger.info('Plugin disabled');
  }
});

ui-injection.code:
const badge = ctx.h('div', {}, 'My Badge');
const handle = await ctx.api.ui.inject('body', badge, 'append');
// handle.remove() undoes the injection (also happens automatically on disable);
// handle.update(newVnode) replaces its attrs/children in place.

middleware.code:
window.CardSpoke.Middleware.register({
  name: 'my-middleware',
  priority: 10,
  operations: ['card.save'],
  handler: async function(mwCtx, next) {
    console.log('Before save:', mwCtx.args[0]);
    await next(); // Call next middleware
    console.log('After save');
  }
});
